import numpy as np,json
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from control import R,state,send,pose
A=[0,0,0,.0825,-.0825,0,.088];D=[.333,0,.316,0,.384,0,0];AL=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
def fk(q):
 T=np.eye(4)
 for a,d,al,th in zip(A,D,AL,q):
  ca,sa,ct,st=np.cos(al),np.sin(al),np.cos(th),np.sin(th)
  T=T@np.array([[ct,-st,0,a],[ca*st,ca*ct,-sa,-d*sa],[sa*st,sa*ct,ca,d*ca],[0,0,0,1]])
 return T

def fit():
 c=json.load(open(R/'calibration.json'));ms=[c['initial']]+c['samples']
 Q=[np.array(m['proprio']['now'][4:11]) for m in ms]
 P=[pose(m) for m in ms];F=[fk(q) for q in Q]
 def fun(x):
  rb=Rotation.from_rotvec(x[:3]).as_matrix();re=Rotation.from_rotvec(x[3:6]).as_matrix();t=x[6:9];e=x[9:12]
  return np.concatenate([np.r_[rb@f[:3,3]+t+rb@f[:3,:3]@e-p,Rotation.from_matrix(rb@f[:3,:3]@re@rr.T).as_rotvec()] for f,(p,rr) in zip(F,P)])
 x=np.zeros(12);x[6:9]=[2.3,-2.3,1];x[9:12]=[0,0,.2];x[3:6]=Rotation.from_matrix(F[0][:3,:3].T@P[0][1]).as_rotvec()
 sol=least_squares(fun,x,max_nfev=2000,xtol=1e-13,gtol=1e-13,ftol=1e-13)
 print('fit',sol.x,'error',np.linalg.norm(sol.fun), 'max',max(abs(sol.fun)))
 np.save(R/'kinfit.npy',sol.x)
