 def __init__(self):
  x=np.load(R/'kinfit.npy');self.rb=Rotation.from_rotvec(x[:3]).as_matrix();self.re=Rotation.from_rotvec(x[3:6]).as_matrix();self.t=x[6:9];self.e=x[9:12]
 def pred(self,q):
  f=fk(q);return self.rb@(f[:3,3]+f[:3,:3]@self.e)+self.t,self.rb@f[:3,:3]@self.re
 def ik(self,p,rot=None,q0=None):
  if q0 is None:q0=np.array(state()['proprio']['now'][4:11])
  def fun(q):
   pp,rr=self.pred(q)
   return np.r_[(pp-p)*4,Rotation.from_matrix(rr@rot.T).as_rotvec() if rot is not None else [],.015*(q-q0)]
  sol=least_squares(fun,q0,bounds=([-2.85,-1.75,-2.85,-3.05,-2.85,-.01,-2.85],[2.85,1.75,2.85,-.07,2.85,3.7,2.85]),max_nfev=500)
  return sol.x,self.pred(sol.x),np.linalg.norm(sol.fun)
if __name__=='__main__':fit()
